/*
 * RING_$SEND_OS - Send an OS packet on a ring channel
 *
 * Original address: 0x00E77C60 (SAU2 map: RING_PROC, RING_$SEND_OS at E77C60)
 * Size: 722 bytes (0x00E77C60 .. 0x00E77F31)
 * Generated by: Claude Opus 5.5
 *
 * The ring driver's send_os entry (driver record +0x44, RING_$CTL + 0x55C),
 * called by MAC_OS_$SEND.  It builds the 0x1C-byte ring header in front of
 * the caller's header bytes - in a fresh NETBUF header page unless the
 * caller's header already starts at page offset 0x1C - sends it with
 * RING_$SENDP when the packet is addressed to another node or broadcast,
 * and loops it back through MAC_OS_$DEMUX when it is addressed to this node
 * or broadcast.
 *
 * Frame (link.w A6,-0xf0; D2-D6/A2-A5 saved; A5 = RING_$CTL):
 *   (0x08,A6) unit         (0x0A,A6) channel_ptr   (0x0E,A6) pkt (D6)
 *   (0x12,A6) bytes_sent   (0x16,A6) status_ret
 *   (-0x50,A6) pkt_copy    the 0x4C-byte record handed to MAC_OS_$DEMUX
 *   (-0x60,A6) new_pages   NET_IO_$COPY_PACKET's four payload pages
 *   (-0xA4,A6) new_hdr     NET_IO_$COPY_PACKET's header VA
 *   (-0xB8,A6) status      RING_$SENDP / loopback status
 *   (-0xBC,A6) hdr_va      the ring header being built (also -0xE4)
 *   (-0xCC,A6) .. (-0xC0,A6)  four longwords whose address is RING_$SENDP's
 *              data_desc: pkt->data_pages[0], the NETBUF header VA,
 *              the loopback source VA (0) and one never-written cell
 *   (-0xD0,A6) hdr_pa      (-0xD4,A6) result      (-0xD6,A6) send_opts (0)
 *   (-0xDA,A6) demux_flag  (byte, cleared before MAC_OS_$DEMUX)
 *   D3w unit, D4b "header page allocated", D5w header length
 *
 * Quirks reproduced:
 *   - The data-length and destination checks (0x00E77D60, 0x00E77D80) run
 *     after a NETBUF header page may have been taken, and their error exits
 *     jump straight to the epilogue: the page is not returned.
 *   - A loopback failure is not reported: *status_ret keeps RING_$SENDP's
 *     status (broadcast) or status_$ok (0x00E77E58).
 *   - The ring header's first longword is the destination node, built from
 *     the two link-address words, and is compared with the source (this
 *     node) to decide between the wire and loopback.
 */

#include "ring/ring_internal.h"
#include "mac_os/mac_os.h"
#include "node/node.h"
#include "os/os.h"

/* The caller's header follows the 0x1C-byte ring header (0x00E77CF8) */
#define RING_SEND_OS_HDR_SIZE    0x1C
/* Largest caller header: `cmpi.l #0x3c8,(0x1c,A2)` at 0x00E77CD4 */
#define RING_SEND_OS_MAX_HDR     0x3C8
/* A prebuilt header page keeps its DMA address in its last longword */
#define RING_SEND_OS_PAGE_PA_OFF 0x3FC
/* Only two-word (node id) link addresses: `cmpi.w #0x2,D0w` 0x00E77D80 */
#define RING_SEND_OS_ADDR_WORDS  2

/* Header flag bits written at 0x00E77DAE / 0x00E77DBC */
#define RING_SEND_OS_FLAG_ROUTE      0x01
#define RING_SEND_OS_FLAG_BROADCAST  0x80

void RING_$SEND_OS(uint16_t unit, int16_t *channel_ptr,
                   struct mac_os_$send_pkt_t *pkt, int16_t *bytes_sent,
                   status_$t *status_ret)
{
    mac_os_$send_pkt_t pkt_copy;     /* (-0x50,A6) */
    uint32_t new_pages[4];           /* (-0x60,A6) */
    uint32_t new_hdr;                /* (-0xA4,A6) */
    status_$t status;                /* (-0xB8,A6) */
    uint32_t hdr_va;                 /* (-0xBC,A6) */
    uint32_t data_desc[4];           /* (-0xCC,A6) .. (-0xC0,A6) */
    uint32_t hdr_pa;                 /* (-0xD0,A6) */
    uint16_t result;                 /* (-0xD4,A6) */
    uint16_t send_opts;              /* (-0xD6,A6) */
    int8_t demux_flag;               /* (-0xDA,A6) */
    int8_t hdr_allocated;            /* D4b */
    uint16_t hdr_len;                /* D5w */
    int16_t channel;
    ring_unit_t *u;
    ring_$pkt_hdr_t *hdr;
    uint32_t page;

    /* 0x00E77C7A-0x00E77C86 */
    send_opts = 0;
    *bytes_sent = 0;
    data_desc[0] = pkt->data_pages[0];

    /* 0x00E77C8C-0x00E77CB0: the unit must be started with transmit on */
    u = &RING_$CTL.units[(int16_t)unit];
    if ((u->state_flags & RING_UNIT_STARTED) == 0 || (u->tmask & 1) == 0) {
        *status_ret = status_$ring_device_offline;
        return;
    }

    /* 0x00E77CB4-0x00E77CD0: an open channel 1..10 */
    channel = *channel_ptr;
    if (channel == 0 || (uint16_t)channel > RING_MAX_CHANNELS ||
        RING_UNIT_CHANNEL(u, channel).flags >= 0) {
        *status_ret = status_$ring_channel_not_open;
        return;
    }

    /* 0x00E77CD4-0x00E77CE8 */
    if (pkt->hdr_desc.length > RING_SEND_OS_MAX_HDR) {
        *status_ret = status_$ring_illegal_header_length;
        return;
    }

    /* 0x00E77CEC-0x00E77D54: find room for the ring header */
    hdr_allocated = 0;
    if ((pkt->hdr_desc.address & 0x3FF) != RING_SEND_OS_HDR_SIZE) {
        /* 0x00E77D00-0x00E77D3E: copy the caller's header into a new page */
        hdr_allocated = (int8_t)0xFF;
        NETBUF_$GET_HDR(&hdr_pa, &data_desc[1]);
        hdr_va = data_desc[1];
        hdr_len = (uint16_t)pkt->hdr_desc.length;
        OS_$DATA_COPY(ARCH_VA_TO_PTR(pkt->hdr_desc.address),
                      ARCH_VA_TO_PTR(hdr_va + RING_SEND_OS_HDR_SIZE),
                      (uint32_t)hdr_len);
    } else {
        /* 0x00E77D44-0x00E77D54: the header already sits at page + 0x1C */
        page = pkt->hdr_desc.address & 0xFFFFFC00u;   /* andi.w #-0x400,D1w */
        hdr_pa = *(uint32_t *)ARCH_VA_TO_PTR(page + RING_SEND_OS_PAGE_PA_OFF);
        hdr_va = page;
    }

    /* 0x00E77D58-0x00E77D74 */
    hdr_len = (uint16_t)(RING_SEND_OS_HDR_SIZE + (uint16_t)pkt->hdr_desc.length);
    if ((int32_t)pkt->data_length > RING_MAX_DATA_LEN) {
        *status_ret = status_$ring_invalid_data_length;
        return;
    }

    /* 0x00E77D78-0x00E77DA6: destination node from the link address */
    hdr = (ring_$pkt_hdr_t *)ARCH_VA_TO_PTR(hdr_va);
    if (pkt->link_addr.n_words != RING_SEND_OS_ADDR_WORDS) {
        *status_ret = status_$ring_illegal_dest_address;
        return;
    }
    hdr->msg_type = ((uint32_t)pkt->link_addr.addr[0] << 16) |
                    (uint32_t)pkt->link_addr.addr[1];

    /* 0x00E77DAA-0x00E77DEA: the rest of the ring header */
    hdr->flags = RING_SEND_OS_FLAG_ROUTE;
    if (pkt->is_broadcast < 0) {
        hdr->flags |= RING_SEND_OS_FLAG_BROADCAST;
    }
    hdr->_r05[0] = 0;                 /* andi.l #0xff0000ff,(0x4,A2) */
    hdr->_r05[1] = 0;
    hdr->flags7 = 0;
    hdr->src_id = NODE_$ME;
    hdr->chksum = 1;                  /* move.b #0x1,(0xd,A0) */
    hdr->hdr_len = hdr_len;
    hdr->data_len = (uint16_t)pkt->data_length;
    hdr->route_info = pkt->frame_type;

    /* 0x00E77DF0-0x00E77E5C: another node, or broadcast: on the wire */
    if (hdr->msg_type != hdr->src_id || (int8_t)hdr->flags < 0) {
        ML_$LOCK(ML_LOCK_NET_IO);
        RING_$SENDP(&unit, hdr_pa, hdr, hdr_len, data_desc, 0,
                    (uint16_t)pkt->data_length, &send_opts, &result, &status);
        *bytes_sent = (int16_t)result;
        *status_ret = status;
        ML_$UNLOCK(ML_LOCK_NET_IO);
    } else {
        *status_ret = status_$ok;     /* 0x00E77E58 */
    }

    /* 0x00E77E5E-0x00E77F18: this node, or broadcast: loop it back */
    if (hdr->msg_type == hdr->src_id || (int8_t)hdr->flags < 0) {
        data_desc[2] = 0;
        pkt_copy = *pkt;              /* 0x13 longwords, 0x00E77E7C */
        NET_IO_$COPY_PACKET(&hdr_va, hdr_len, data_desc[2], &data_desc[0],
                            (uint16_t)pkt_copy.data_length, &new_hdr,
                            new_pages, &status);
        if (status == status_$ok) {
            pkt_copy.hdr_desc.address = new_hdr + RING_SEND_OS_HDR_SIZE;
            pkt_copy.data_pages[0] = new_pages[0];
            pkt_copy.data_pages[1] = new_pages[1];
            pkt_copy.data_pages[2] = new_pages[2];
            pkt_copy.data_pages[3] = new_pages[3];
            demux_flag = 0;
            MAC_OS_$DEMUX((mac_os_$rcv_pkt_t *)(void *)&pkt_copy,
                          &RING_$CTL.port_array[(int16_t)unit], &demux_flag,
                          &status);
            if (status != status_$ok) {
                NETBUF_$RTN_HDR(&new_hdr);
                PKT_$DUMP_DATA(new_pages, (int16_t)pkt_copy.data_length);
            }
        }
    }

    /* 0x00E77F1A-0x00E77F22 */
    if (hdr_allocated < 0) {
        NETBUF_$RTN_HDR(&data_desc[1]);
    }
}
